import 'package:flutter/material.dart';
import 'package:stream_chat_flutter/stream_chat_flutter.dart';

void main() async {
  final client = StreamChatClient('YOUR_API_KEY');
  await client.connectUser(User(id: 'user-id'), 'USER_TOKEN');
  runApp(MaterialApp(
    theme: ThemeData(extensions: [StreamTheme.light()]),
    home: StreamChat(client: client, child: const MyHomePage()),
  ));
}

class MyHomePage extends StatelessWidget {
  const MyHomePage({Key? key}) : super(key: key);
  @override
  Widget build(BuildContext context) => Scaffold(
        appBar: AppBar(title: const Text('Chat')),
        body: const StreamChannelListView(),
      );
}
